export const industries: Industry[] = localize<Industry[]>(industriesSource);

export function getIndustry(slug: string) {
  return industries.find((i) => i.slug === slug);
}

/** Azok az iparágak, amelyek ezt a terméket ajánlják — a termékoldal alján. */
export function industriesForProduct(productSlug: string): Industry[] {
  return industries.filter((i) => i.products.some((p) => p.slug === productSlug));
}
